class Solution {
    public int characterReplacement(String s,int k){
        int[] counts=new int[26];
        int left=0,maxFrequency=0,answer=0;
        for(int right=0;right<s.length();right++){
            maxFrequency=Math.max(maxFrequency,++counts[s.charAt(right)-'A']);
            while(right-left+1-maxFrequency>k)counts[s.charAt(left++)-'A']--;
            answer=Math.max(answer,right-left+1);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun characterReplacement(s:String,k:Int):Int{
        val counts=IntArray(26);
        var left=0;
        var maxFrequency=0;
        var answer=0;
        for(right in s.indices){
            counts[s[right]-'A']++;
            maxFrequency=maxOf(maxFrequency,counts[s[right]-'A']);
            while(right-left+1-maxFrequency>k)counts[s[left++]-'A']--;
            answer=maxOf(answer,right-left+1)
        };
        return answer
    }
}

